/**
 * Explicit push-destination parsing for git-validator (#3455).
 *
 * The guard denied worktree pushes as "direct to main" because cwd
 * resolution fails (shell_cwd never lands on disk, #3411) and the fallback
 * reads the primary checkout. When a push NAMES its destination, that verdict
 * needs no cwd at all.
 *
 * The security-relevant cases are the null ones: an unknowable destination
 * must never be laundered into an allow.
 */

import { describe, it, expect } from 'vitest';
import { extractPushDestinations } from '../../pretool/bash/git-validator.js';

describe('extractPushDestinations (#3455)', () => {
  describe('resolvable destinations', () => {
    it('reads a -u push to a feature branch', () => {
      expect(extractPushDestinations('git push -u origin fix/git-validator')).toEqual([
        'fix/git-validator',
      ]);
    });

    it('reads the destination side of a colon refspec', () => {
      expect(extractPushDestinations('git push origin HEAD:main')).toEqual(['main']);
    });

    it('ignores flags anywhere in the command', () => {
      expect(
        extractPushDestinations('git push --force-with-lease origin feat/x --no-verify'),
      ).toEqual(['feat/x']);
    });

    it('strips refs/heads/ and a leading +', () => {
      expect(extractPushDestinations('git push origin HEAD:+refs/heads/feat/y')).toEqual(['feat/y']);
    });

    it('handles git -C <path> push', () => {
      expect(extractPushDestinations('git -C /tmp/wt push origin feat/z')).toEqual(['feat/z']);
    });

    it('reads the real-world commit-then-push chain from the report', () => {
      expect(
        extractPushDestinations(
          'git add -A && git commit -q -m "docs: x" && git push -u origin fix/stale-message',
        ),
      ).toEqual(['fix/stale-message']);
    });

    it('collects every push in a compound command', () => {
      expect(extractPushDestinations('git push origin a && git push origin b')).toEqual(['a', 'b']);
    });
  });

  describe('unknowable destinations must return null', () => {
    it('bare git push resolves through upstream, not the string', () => {
      expect(extractPushDestinations('git push')).toBeNull();
    });

    it('a lone remote leaves the branch implicit', () => {
      expect(extractPushDestinations('git push origin')).toBeNull();
    });

    it('git push --force-with-lease with no refspec', () => {
      expect(extractPushDestinations('git push --force-with-lease')).toBeNull();
    });

    // The laundering case: one named feature destination must not vouch for a
    // sibling push whose target is unknown.
    it('returns null when ANY push in the chain is unresolvable', () => {
      expect(extractPushDestinations('git push origin feat/x && git push')).toBeNull();
    });

    it('returns null when there is no push at all', () => {
      expect(extractPushDestinations('git commit -m x')).toBeNull();
    });
  });

  describe('does not swallow a following command as its own operands', () => {
    it('stops at the shell separator', () => {
      expect(extractPushDestinations('git push origin feat/x && echo main')).toEqual(['feat/x']);
    });

    it('stops at a semicolon', () => {
      expect(extractPushDestinations('git push origin feat/x; git log main')).toEqual(['feat/x']);
    });
  });
});
